    denom = (maxup + maxdn).replace(0, np.nan)
    return (maxup / denom)


def f_dist_low(c, v, o, h, l, m, win=60):
    return (c / c.rolling(win).min() - 1.0)


FACTORS = {
    "drawup_40": {"fn": f_drawup, "params": {"win": 40}},
    "drawup_60": {"fn": f_drawup, "params": {"win": 60}},
