lib_panel = pd.read_csv(io.StringIO(zlib.decompress(raw).decode()), index_col=0, parse_dates=True)
lib_panel.index = pd.DatetimeIndex(lib_panel.index)

fwd10 = fwd_returns(close, 10)
panels = {}
for fid, spec in FACTORS.items():
