    'curv_20x60': build_factor('curv_20x60', v3),
    'cn_resid_vol_20': build_factor('cn_resid_vol_20', v4),
    'xau_up_resilience_60': build_factor('xau_up_resilience_60', v5),
    'spx_dd_resilience_60': build_factor('spx_dd_resilience_60', v6),
