print(pd.DataFrame(rets).T.round(1).to_string())

print("\n=== Macro recent moves (%) ===")
for name, col in mac.items():
    v = col.dropna()
    out = {}
    for k in [10,20,60]:
        if len(v)>k:
            out[f'r{k}'] = (v.iloc[-1]/v.iloc[-1-k]-1)*100
    print(name, {k:round(vv,1) for k,vv in out.items()}, "last", round(v.iloc[-1],3))
